FILES = {'backend.py': '"""TradePilot private backend. Broker access is restricted to login/profile/quotes."""\nimport base64\nimport copy\nimport datetime as dt\nimport hashlib\nimport hmac\nimport json\nimport math\nimport os\nfrom pathlib import Path\nimport re\nimport socket\nimport struct\nimport tempfile\nimport threading\nimport time\nimport uuid\nfrom collections import defaultdict\nfrom http.server import BaseHTTPRequestHandler, ThreadingHTTPServer\nfrom urllib.parse import urlsplit, parse_qs\nfrom urllib.request import Request, urlopen\n\nROOT = Path(__file__).resolve().parent\nIST = dt.timezone(dt.timedelta(hours=5, minutes=30))\nBASE = "https://apiconnect.angelone.in"\nLOGIN = "/rest/auth/angelbroking/user/v1/loginByPassword"\nPROFILE = "/rest/secure/angelbroking/user/v1/getProfile"\nQUOTE = "/rest/secure/angelbroking/market/v1/quote/"\nMASTER = "https://margincalculator.angelbroking.com/OpenAPI_File/files/OpenAPIScripMaster.json"\nINDEX = {"NIFTY": "99926000", "BANKNIFTY": "99926009"}\nYAHOO_INDEX = {"NIFTY": "%5ENSEI", "BANKNIFTY": "%5ENSEBANK"}\nNSE_HOLIDAYS = {"2026-11-24", "2026-12-25"}\nDEFAULT_SCANNER_CFG = {"autoTrade": False, "maxDailyLoss": 3000, "maxDailyTrades": 4}\nBACKTEST_PROOF = {\n    "period": "2026-08-25 to 2026-11-20 (60 trading days)",\n    "capital": 100000,\n    "combined": {\n        "trades": 88, "winRate": 35.2, "netPnl": 22370, "returnPct": 22.4,\n        "profitFactor": 1.27, "maxDrawdown": 12416, "avgWin": 3384, "avgLoss": 1448,\n    },\n    "NIFTY": {\n        "strategy": "PDH/PDL Break & Hold (1:3 R:R + EMA20 Trail)",\n        "lotSize": 65, "trades": 42, "winRate": 38.1, "netPnl": 11719,\n        "profitFactor": 1.34, "maxDrawdown": 7378,\n    },\n    "BANKNIFTY": {\n        "strategy": "MTF 20-EMA Trend Pullback (No-Chop 1:3 R:R + BE 1.5R)",\n        "lotSize": 30, "trades": 46, "winRate": 32.6, "netPnl": 10651,\n        "profitFactor": 1.22, "maxDrawdown": 16108,\n    },\n}\n\n\nclass AppError(Exception):\n    def __init__(self, message, status=400):\n        super().__init__(message)\n        self.status = status\n\n\ndef read_env(path):\n    cfg = {}\n    for line in Path(path).read_text().splitlines():\n        if "=" in line and not line.lstrip().startswith("#"):\n            k, v = line.split("=", 1)\n            cfg[k.strip()] = v.strip().strip(\'"\').strip("\'")\n    return cfg\n\n\ndef atomic_json(path, value):\n    fd, tmp = tempfile.mkstemp(prefix=".tp-", dir=path.parent)\n    try:\n        with os.fdopen(fd, "w") as f:\n            if hasattr(os, "fchmod"):\n                os.fchmod(f.fileno(), 0o600)\n            json.dump(value, f, allow_nan=False)\n            f.flush()\n            os.fsync(f.fileno())\n        os.replace(tmp, path)\n    finally:\n        if os.path.exists(tmp):\n            os.unlink(tmp)\n\n\ndef positive(value, label):\n    try:\n        n = float(value)\n    except (TypeError, ValueError):\n        raise AppError(label + " must be a positive number.")\n    if not math.isfinite(n) or n <= 0:\n        raise AppError(label + " must be a positive number.")\n    return n\n\n\ndef totp(secret, now=None):\n    s = secret.replace(" ", "").upper()\n    key = base64.b32decode(s + "=" * ((-len(s)) % 8))\n    digest = hmac.new(key, struct.pack(">Q", int(time.time() if now is None else now) // 30), hashlib.sha1).digest()\n    offset = digest[-1] & 15\n    return str((struct.unpack(">I", digest[offset:offset + 4])[0] & 0x7fffffff) % 1000000).zfill(6)\n\n\ndef now_ist():\n    return dt.datetime.now(IST)\n\n\ndef now_iso():\n    return now_ist().isoformat()\n\n\ndef today_ist():\n    return now_ist().date().isoformat()\n\n\ndef market_hours(now=None):\n    n = now or now_ist()\n    if n.date().isoformat() in NSE_HOLIDAYS:\n        return False\n    return n.weekday() < 5 and dt.time(9, 15) <= n.time() < dt.time(15, 30)\n\n\ndef estimate_option_charges(buy_price, sell_price, qty):\n    """Estimate April 2026 NSE options round-trip charges (INR)."""\n    buy_val = max(0.0, float(buy_price)) * qty\n    sell_val = max(0.0, float(sell_price)) * qty\n    turnover = buy_val + sell_val\n    brokerage = 40.0  # Rs 20 buy + Rs 20 sell\n    stt = sell_val * 0.0015  # 0.15% on sell premium (w.e.f. Apr 1, 2026)\n    exch_sebi = turnover * 0.00036  # NSE txn + SEBI + IPFT approx\n    stamp = buy_val * 0.00003  # 0.003% on buy value\n    gst = 0.18 * (brokerage + exch_sebi)\n    return round(brokerage + stt + exch_sebi + stamp + gst, 2)\n\n\ndef calc_ema(vals, period):\n    out, k = [], 2.0 / (period + 1)\n    for i, v in enumerate(vals):\n        out.append(v if i == 0 else v * k + out[-1] * (1.0 - k))\n    return out\n\n\ndef calc_atr(bars, period=14):\n    trs, out = [], []\n    for i, b in enumerate(bars):\n        tr = b["h"] - b["l"] if i == 0 else max(\n            b["h"] - b["l"], abs(b["h"] - bars[i - 1]["c"]), abs(b["l"] - bars[i - 1]["c"])\n        )\n        trs.append(tr)\n        out.append(sum(trs) / len(trs) if i < period else (out[-1] * (period - 1) + tr) / period)\n    return out\n\n\ndef normalize_instruments(rows):\n    contracts = {}\n    today = now_ist().date()\n    for r in rows:\n        if r.get("exch_seg") != "NFO" or r.get("instrumenttype") != "OPTIDX" or r.get("name") not in INDEX:\n            continue\n        try:\n            expiry = dt.datetime.strptime(r["expiry"], "%d%b%Y").date()\n            if expiry < today:\n                continue\n            symbol = r["symbol"]\n            if not re.fullmatch(r"[A-Za-z0-9.-]+", symbol) or symbol[-2:] not in ("CE", "PE"):\n                continue\n            token = str(r["token"])\n            if not token.isdigit():\n                continue\n            lot = int(r["lotsize"])\n            strike = positive(r["strike"], "strike") / 100\n            if lot <= 0:\n                continue\n            contracts[token] = dict(token=token, tradingSymbol=symbol, underlying=r["name"],\n                                    expiry=expiry.isoformat(), strike=strike, lotSize=lot,\n                                    optionType=symbol[-2:], exchange="NFO")\n        except (KeyError, ValueError, TypeError, AppError):\n            continue\n    return contracts\n\n\nclass Broker:\n    def __init__(self, cfg, root):\n        self.cfg, self.root = cfg, root\n        self.session = {}\n        self.connected = False\n        self.checked = 0\n        self.login_after = 0\n        self.last_quote = 0\n        self.cache = {}\n        self.contracts = {}\n        self.master_day = ""\n        try:\n            self.session = json.loads((root / ".angel-session.json").read_text())\n        except (OSError, ValueError):\n            pass\n\n    def request(self, path, payload=None):\n        if path not in (LOGIN, PROFILE, QUOTE):\n            raise AppError("Broker operation is not allowed.", 403)\n        headers = {"Content-Type": "application/json", "Accept": "application/json",\n                   "X-UserType": "USER", "X-SourceID": "WEB",\n                   "X-ClientLocalIP": "127.0.0.1", "X-ClientPublicIP": self.cfg["ANGEL_PUBLIC_IP"],\n                   "X-MACAddress": ":".join(re.findall("..", f"{uuid.getnode():012x}")),\n                   "X-PrivateKey": self.cfg["ANGEL_API_KEY"]}\n        if path != LOGIN:\n            headers["Authorization"] = "Bearer " + self.session.get("jwtToken", "")\n        body = None if payload is None else json.dumps(payload).encode()\n        try:\n            with urlopen(Request(BASE + path, data=body, headers=headers), timeout=20) as response:\n                data = json.load(response)\n        except Exception:\n            raise AppError("Angel One returned a network or non-JSON error. Try again later.", 502)\n        if not isinstance(data, dict) or data.get("status") is not True:\n            code = str(data.get("errorcode", "")) if isinstance(data, dict) else ""\n            if not re.fullmatch(r"[A-Za-z0-9_-]{0,40}", code):\n                code = ""\n            raise AppError("Angel One rejected the request" + (": " + code if code else "."), 502)\n        return data.get("data")\n\n    def login(self):\n        if time.time() < self.login_after:\n            raise AppError("Login retry is cooling down. Check server settings.", 503)\n        self.login_after = time.time() + 300\n        data = self.request(LOGIN, {"clientcode": self.cfg["ANGEL_CLIENT_CODE"],\n                                   "password": self.cfg["ANGEL_PIN"],\n                                   "totp": totp(self.cfg["ANGEL_TOTP_SECRET"])})\n        if not isinstance(data, dict) or not data.get("jwtToken"):\n            raise AppError("Angel One did not return a login token.", 502)\n        self.session = {k: data.get(k) for k in ("jwtToken", "refreshToken", "feedToken")}\n        atomic_json(self.root / ".angel-session.json", self.session)\n\n    def ensure(self):\n        if self.connected and time.time() - self.checked < 120:\n            return\n        self.connected = False\n        try:\n            self.request(PROFILE)\n        except AppError:\n            self.login()\n            self.request(PROFILE)\n        self.connected, self.checked = True, time.time()\n\n    def instruments(self):\n        today = today_ist()\n        if self.master_day == today and self.contracts:\n            return self.contracts\n        path = self.root / ".instrument-cache.json"\n        try:\n            saved = json.loads(path.read_text())\n            if saved["day"] == today and saved["contracts"]:\n                self.contracts, self.master_day = saved["contracts"], today\n                return self.contracts\n        except (OSError, KeyError, ValueError):\n            pass\n        try:\n            with urlopen(MASTER, timeout=60) as response:\n                rows = json.load(response)\n            parsed = normalize_instruments(rows)\n            if not parsed:\n                raise ValueError()\n        except Exception:\n            raise AppError("Could not load today\'s option instrument list.", 503)\n        atomic_json(path, {"day": today, "contracts": parsed})\n        self.contracts, self.master_day = parsed, today\n        return parsed\n\n    def quotes(self, pairs, force=False):\n        self.ensure()\n        pairs = list(dict.fromkeys(pairs))\n        missing = [p for p in pairs if force or p not in self.cache or time.time() - self.cache[p]["received"] > 3]\n        for offset in range(0, len(missing), 50):\n            batch = missing[offset:offset + 50]\n            time.sleep(max(0, 1.05 - (time.monotonic() - self.last_quote)))\n            groups = {}\n            for exchange, token in batch:\n                groups.setdefault(exchange, []).append(token)\n                self.cache.pop((exchange, token), None)\n            self.last_quote = time.monotonic()\n            result = self.request(QUOTE, {"mode": "FULL", "exchangeTokens": groups}) or {}\n            for q in result.get("fetched", []):\n                key = (str(q.get("exchange")), str(q.get("symbolToken")))\n                if key not in batch:\n                    continue\n                try:\n                    price = positive(q.get("ltp"), "price")\n                except AppError:\n                    continue\n                stamp = q.get("exchFeedTime") or q.get("exchTradeTime")\n                feed = 0\n                if stamp:\n                    for fmt in ("%d-%b-%Y %H:%M:%S", "%d-%m-%Y %H:%M:%S", "%Y-%m-%d %H:%M:%S"):\n                        try:\n                            feed = dt.datetime.strptime(stamp, fmt).replace(tzinfo=IST).timestamp()\n                            break\n                        except (ValueError, TypeError):\n                            pass\n\n                def finite(v):\n                    try:\n                        n = float(v)\n                        return n if math.isfinite(n) else 0\n                    except (ValueError, TypeError):\n                        return 0\n\n                self.cache[key] = {"ltp": price, "netChange": finite(q.get("netChange")),\n                                   "percentChange": finite(q.get("percentChange")), "received": time.time(),\n                                   "feed": feed, "asOf": stamp}\n        return {p: self.cache[p] for p in pairs if p in self.cache}\n\n    def trade_price(self, contract, quotes=None):\n        if not market_hours():\n            raise AppError("Paper fills are paused outside regular market hours.")\n        key = ("NFO", contract["token"])\n        q = (quotes if quotes is not None else self.quotes([key])).get(key)\n        if not q or time.time() - q["received"] > 10 or not -5 <= time.time() - q["feed"] <= 60:\n            raise AppError("No fresh exchange-timestamped price. Paper fill paused.", 503)\n        return q["ltp"]\n\n\nclass Paper:\n    def __init__(self, path):\n        self.path = path\n        if path.exists():\n            self.data = json.loads(path.read_text())\n            if self.data.get("version") != 1:\n                raise RuntimeError("Unsupported paper-state file; refusing to reset.")\n        else:\n            self.data = {"version": 1, "realized": 0, "positions": [], "orders": [], "rules": []}\n        self._ensure_defaults()\n\n    def _ensure_defaults(self):\n        self.data.setdefault("estimatedCharges", 0.0)\n        cfg = self.data.setdefault("scannerCfg", dict(DEFAULT_SCANNER_CFG))\n        for k, v in DEFAULT_SCANNER_CFG.items():\n            cfg.setdefault(k, v)\n        self.data.setdefault("armedSetupIds", [])\n\n    def save(self):\n        atomic_json(self.path, self.data)\n\n    def daily_stats(self):\n        today = today_ist()\n        today_orders = [o for o in self.data["orders"] if str(o.get("time", "")).startswith(today)]\n        realized_today = sum(float(o.get("pnl") or 0) for o in today_orders if o.get("pnl") is not None)\n        charges_today = sum(float(o.get("charges") or 0) for o in today_orders if o.get("charges") is not None)\n        open_pnl = sum(float(p.get("pnl") or 0) for p in self.data["positions"])\n        scanner_fills = [o for o in today_orders if o.get("status") == "FILLED" and o.get("source") == "SCANNER"]\n        by_index = {"NIFTY": 0, "BANKNIFTY": 0}\n        for o in scanner_fills:\n            sym = str(o.get("symbol", ""))\n            if sym.startswith("BANKNIFTY"):\n                by_index["BANKNIFTY"] += 1\n            elif sym.startswith("NIFTY"):\n                by_index["NIFTY"] += 1\n        total_today = round(realized_today - charges_today + open_pnl, 2)\n        max_loss = float(self.data["scannerCfg"].get("maxDailyLoss", 3000))\n        return {\n            "date": today,\n            "todayPnl": total_today,\n            "scannerTradesToday": len(scanner_fills),\n            "byIndexToday": by_index,\n            "maxDailyLoss": max_loss,\n            "maxDailyTrades": int(self.data["scannerCfg"].get("maxDailyTrades", 4)),\n            "killSwitchHit": total_today <= -max_loss,\n        }\n\n    def snapshot(self):\n        self._ensure_defaults()\n        d = copy.deepcopy(self.data)\n        pnl = sum(p["pnl"] for p in d["positions"])\n        equity = 100000 + d["realized"] + pnl\n        used = sum(p["reserved"] for p in d["positions"])\n        charges = round(float(d.get("estimatedCharges", 0.0)), 2)\n        d["account"] = {\n            "equity": round(equity, 2),\n            "available": round(equity - used, 2),\n            "openPnl": round(pnl, 2),\n            "realized": round(d["realized"], 2),\n            "estimatedCharges": charges,\n            "netRealized": round(d["realized"] - charges, 2),\n        }\n        d["daily"] = self.daily_stats()\n        return d\n\n    def validate(self, body, contract):\n        side = str(body.get("side", "")).upper()\n        if side not in ("BUY", "SELL"):\n            raise AppError("Side must be BUY or SELL.")\n        qty = positive(body.get("qty"), "Quantity")\n        if qty != int(qty) or int(qty) % contract["lotSize"] or qty > 100000:\n            raise AppError("Quantity must be a whole lot multiple, at most 100,000.")\n        sl = None if body.get("sl") is None else positive(body["sl"], "Stop-loss")\n        target = None if body.get("target") is None else positive(body["target"], "Target")\n        return side, int(qty), sl, target\n\n    def open(self, body, contract, price, source="MANUAL"):\n        if len(self.data["positions"]) >= 50:\n            raise AppError("Maximum 50 open paper positions.")\n        side, qty, sl, target = self.validate(body, contract)\n        if side == "BUY" and ((sl and sl >= price) or (target and target <= price)):\n            raise AppError("BUY stop-loss must be below entry and target above entry.")\n        if side == "SELL" and ((sl and sl <= price) or (target and target >= price)):\n            raise AppError("SELL stop-loss must be above entry and target below entry.")\n        # Deliberately conservative simulation, not exchange SPAN or broker margin.\n        reserve = price * qty if side == "BUY" else max(price * qty, contract["strike"] * qty * 0.2)\n        if reserve > self.snapshot()["account"]["available"]:\n            raise AppError("Insufficient simulated funds (SELL uses a 20% notional reserve).")\n        risk_pts = round(abs(price - sl), 2) if sl else None\n        p = dict(contract, id=uuid.uuid4().hex, side=side, qty=qty, entry=price, ltp=price,\n                 pnl=0, sl=sl, target=target, reserved=reserve, source=source,\n                 initialRisk=risk_pts, trailed=False)\n        self.data["positions"].append(p)\n        self.record(p, "FILLED", price)\n        return p\n\n    def record(self, p, status, price, pnl=None, charges=None, side=None):\n        self.data["orders"].append({\n            "time": now_iso(), "symbol": p["tradingSymbol"], "side": side or p["side"],\n            "qty": p["qty"], "price": price, "status": status, "pnl": pnl,\n            "charges": charges, "source": p.get("source", "MANUAL"),\n        })\n        self.data["orders"] = self.data["orders"][-2000:]\n\n    def close(self, ident, price, reason="EXIT"):\n        p = next((x for x in self.data["positions"] if x["id"] == ident), None)\n        if not p:\n            raise AppError("Paper position not found.", 404)\n        pnl = (price - p["entry"]) * p["qty"] * (1 if p["side"] == "BUY" else -1)\n        buy_p, sell_p = (p["entry"], price) if p["side"] == "BUY" else (price, p["entry"])\n        charges = estimate_option_charges(buy_p, sell_p, p["qty"])\n        self.data["realized"] += pnl\n        self.data["estimatedCharges"] = round(float(self.data.get("estimatedCharges", 0.0)) + charges, 2)\n        self.data["positions"].remove(p)\n        exit_side = "SELL" if p["side"] == "BUY" else "BUY"\n        self.record(p, reason, price, round(pnl, 2), charges, side=exit_side)\n\n\ndef fetch_yahoo_bars(symbol, rng="5d", interval="5m"):\n    url = f"https://query1.finance.yahoo.com/v8/finance/chart/{symbol}?range={rng}&interval={interval}"\n    req = Request(url, headers={"User-Agent": "Mozilla/5.0"})\n    with urlopen(req, timeout=10) as resp:\n        data = json.load(resp)["chart"]["result"][0]\n    ts = data.get("timestamp") or []\n    q = data["indicators"]["quote"][0]\n    rows = []\n    for i, t in enumerate(ts):\n        o, h, l, c = q["open"][i], q["high"][i], q["low"][i], q["close"][i]\n        if None in (o, h, l, c):\n            continue\n        d = dt.datetime.fromtimestamp(t, IST)\n        rows.append({\n            "date": d.strftime("%Y-%m-%d"), "time": d.strftime("%H:%M"),\n            "o": float(o), "h": float(h), "l": float(l), "c": float(c),\n        })\n    return rows\n\n\ndef merge_bars(base_bars, live_bars):\n    """Merge historical seed bars with live Angel One tick-aggregated bars (live overrides same slot)."""\n    merged = {(b["date"], b["time"]): dict(b) for b in base_bars}\n    for b in live_bars:\n        key = (b["date"], b["time"])\n        if key in merged:\n            old = merged[key]\n            merged[key] = {\n                "date": b["date"], "time": b["time"],\n                "o": old["o"], "h": max(old["h"], b["h"]),\n                "l": min(old["l"], b["l"]), "c": b["c"],\n            }\n        else:\n            merged[key] = dict(b)\n    return [merged[k] for k in sorted(merged.keys())]\n\n\ndef analyze_index_bars(index_name, bars5, bars15, live_spot=None, is_live_market=False, now=None):\n    """Evaluate TradePilot\'s proven Dual-Engine Strategy on 5m & 15m NSE bars."""\n    cur_dt = now or now_ist()\n    cur_day = cur_dt.date().isoformat()\n    cur_mins = cur_dt.hour * 60 + cur_dt.minute\n\n    by_day5, by_day15 = defaultdict(list), defaultdict(list)\n    for b in bars5:\n        by_day5[b["date"]].append(b)\n    for b in bars15:\n        by_day15[b["date"]].append(b)\n    days = sorted(set(by_day5) & set(by_day15))\n    if len(days) < 2:\n        return {"index": index_name, "error": "Insufficient candle history."}\n\n    all15 = [b for d in days for b in by_day15[d]]\n    e9_15, e20_15 = calc_ema([b["c"] for b in all15], 9), calc_ema([b["c"] for b in all15], 20)\n    idx15 = {(b["date"], b["time"]): i for i, b in enumerate(all15)}\n\n    all5 = [b for d in days for b in by_day5[d]]\n    e9_5 = calc_ema([b["c"] for b in all5], 9)\n    e20_5 = calc_ema([b["c"] for b in all5], 20)\n    e50_5 = calc_ema([b["c"] for b in all5], 50)\n    a14_5 = calc_atr(all5, 14)\n    idx5 = {(b["date"], b["time"]): i for i, b in enumerate(all5)}\n\n    daily = {\n        d: {\n            "o": by_day5[d][0]["o"], "h": max(x["h"] for x in by_day5[d]),\n            "l": min(x["l"] for x in by_day5[d]), "c": by_day5[d][-1]["c"],\n        }\n        for d in days\n    }\n\n    last_day = days[-1]\n    prev = daily[days[-2]]\n    pdh, pdl, pdc = round(prev["h"], 2), round(prev["l"], 2), round(prev["c"], 2)\n    db = by_day5[last_day]\n    orb_bars = [x for x in db if x["time"] < "09:30"] or db[:3]\n    orb_h = round(max(x["h"] for x in orb_bars), 2)\n    orb_l = round(min(x["l"] for x in orb_bars), 2)\n\n    mode = "PDH_PDL_BREAK_HOLD" if index_name == "NIFTY" else "MTF_EMA_PULLBACK_NOCHOP"\n    strategy_label = (\n        "PDH/PDL Break & Hold (1:3 R:R)" if index_name == "NIFTY"\n        else "MTF 20-EMA Pullback No-Chop (1:3 R:R)"\n    )\n\n    recent_setups = []\n    for di in range(max(1, len(days) - 3), len(days)):\n        day = days[di]\n        d_prev = daily[days[di - 1]]\n        d_pdh, d_pdl = d_prev["h"], d_prev["l"]\n        ddb = by_day5[day]\n        d_orb = [x for x in ddb if x["time"] < "09:30"]\n        if not d_orb or len(ddb) < 5:\n            continue\n        d_orb_h, d_orb_l = max(x["h"] for x in d_orb), min(x["l"] for x in d_orb)\n        # During live hours on today\'s bars, exclude the still-forming last 5m candle\n        scan_end = len(ddb) - 1 if (is_live_market and day == cur_day and len(ddb) > 4) else len(ddb)\n        for i in range(3, scan_end):\n            b, t = ddb[i], ddb[i]["time"]\n            if t < "09:30" or t > "14:15":\n                continue\n            g5 = idx5[(day, t)]\n            hh, mm = int(t[:2]), int(t[3:])\n            bar_mins = hh * 60 + mm\n            prev15 = ((bar_mins - 15) // 15) * 15\n            t15 = f"{prev15 // 60:02d}:{prev15 % 60:02d}"\n            g15 = idx15.get((day, t15)) or idx15.get((days[di - 1], "15:15"))\n            if g15 is None:\n                continue\n            cur_atr = max(a14_5[g5], 10.0)\n            body = abs(b["c"] - b["o"])\n            bull, bear = b["c"] > b["o"], b["c"] < b["o"]\n            up_w, lo_w = b["h"] - max(b["o"], b["c"]), min(b["o"], b["c"]) - b["l"]\n            pb = ddb[i - 1]\n            htf_bull = e9_15[g15] > e20_15[g15] and all15[g15]["c"] > e20_15[g15]\n            htf_bear = e9_15[g15] < e20_15[g15] and all15[g15]["c"] < e20_15[g15]\n            sig, sl, reason = None, None, ""\n\n            if mode == "PDH_PDL_BREAK_HOLD":\n                if htf_bull and b["c"] > d_pdh and b["l"] <= d_pdh + cur_atr * 0.6 and bull and b["c"] > e9_5[g5] and b["c"] > pb["h"]:\n                    sig = "CE"\n                    sl = min(b["l"], d_pdh - cur_atr * 0.35)\n                    reason = f"15m bullish + 5m close above PDH ({d_pdh:.1f}) holding retest above EMA9"\n                elif htf_bear and b["c"] < d_pdl and b["h"] >= d_pdl - cur_atr * 0.6 and bear and b["c"] < e9_5[g5] and b["c"] < pb["l"]:\n                    sig = "PE"\n                    sl = max(b["h"], d_pdl + cur_atr * 0.35)\n                    reason = f"15m bearish + 5m close below PDL ({d_pdl:.1f}) holding retest below EMA9"\n            else:\n                if "11:30" <= t < "13:15":\n                    continue\n                if htf_bull and e9_5[g5] > e20_5[g5] > e50_5[g5] and b["c"] > d_orb_h:\n                    touched = b["l"] <= e20_5[g5] * 1.0005 or pb["l"] <= e20_5[g5 - 1] * 1.0005\n                    if touched and bull and b["c"] > e9_5[g5] and (b["c"] > pb["h"] or lo_w >= body * 1.3):\n                        sig = "CE"\n                        sl = min(b["l"], pb["l"]) - cur_atr * 0.15\n                        reason = f"15m+5m uptrend above ORB ({d_orb_h:.1f}) + 20-EMA pullback bounce"\n                elif htf_bear and e9_5[g5] < e20_5[g5] < e50_5[g5] and b["c"] < d_orb_l:\n                    touched = b["h"] >= e20_5[g5] * 0.9995 or pb["h"] >= e20_5[g5 - 1] * 0.9995\n                    if touched and bear and b["c"] < e9_5[g5] and (b["c"] < pb["l"] or up_w >= body * 1.3):\n                        sig = "PE"\n                        sl = max(b["h"], pb["h"]) + cur_atr * 0.15\n                        reason = f"15m+5m downtrend below ORB ({d_orb_l:.1f}) + 20-EMA pullback rejection"\n\n            if sig and sl is not None:\n                entry = round(b["c"], 2)\n                risk = round((entry - sl) if sig == "CE" else (sl - entry), 2)\n                if cur_atr * 0.8 <= risk <= cur_atr * 2.8:\n                    target = round(entry + risk * 3.0 if sig == "CE" else entry - risk * 3.0, 2)\n                    # A setup is LIVE only if it is TODAY\'s session AND closed within the last 12 minutes\n                    bar_close_mins = bar_mins + 5\n                    age_mins = cur_mins - bar_close_mins\n                    is_fresh = is_live_market and day == cur_day and 0 <= age_mins <= 12\n                    recent_setups.append({\n                        "id": f"{index_name}-{day}-{t}-{sig}",\n                        "index": index_name,\n                        "strategy": strategy_label,\n                        "mode": mode,\n                        "direction": sig,\n                        "date": day,\n                        "time": t,\n                        "status": "LIVE" if is_fresh else "PREVIEW",\n                        "spotEntry": entry,\n                        "spotSl": round(sl, 2),\n                        "spotTarget": target,\n                        "spotRisk": risk,\n                        "rr": 3.0,\n                        "reason": reason,\n                    })\n\n    last_bar = db[-1]\n    g5_last = idx5[(last_day, last_bar["time"])]\n    g15_last = len(all15) - 1\n    htf_bias = "NEUTRAL"\n    if e9_15[g15_last] > e20_15[g15_last] and all15[g15_last]["c"] > e20_15[g15_last]:\n        htf_bias = "BULLISH"\n    elif e9_15[g15_last] < e20_15[g15_last] and all15[g15_last]["c"] < e20_15[g15_last]:\n        htf_bias = "BEARISH"\n\n    now_t = cur_dt.strftime("%H:%M")\n    if not is_live_market:\n        regime = "MARKET_CLOSED"\n    elif now_t < "09:30":\n        regime = "OPEN_VOLATILITY"\n    elif index_name == "BANKNIFTY" and "11:30" <= now_t < "13:15":\n        regime = "MIDDAY_CHOP_SKIP"\n    elif now_t > "14:15":\n        regime = "LATE_SESSION"\n    else:\n        regime = "PRIME_SCANNING"\n\n    spot_px = round(float(live_spot), 2) if live_spot else round(last_bar["c"], 2)\n    live_setup = next((s for s in reversed(recent_setups) if s["status"] == "LIVE"), None)\n    latest_setup = live_setup or (recent_setups[-1] if recent_setups else None)\n\n    return {\n        "index": index_name,\n        "sessionDate": last_day,\n        "lastBarTime": last_bar["time"],\n        "spot": spot_px,\n        "strategy": strategy_label,\n        "htfBias": htf_bias,\n        "regime": regime,\n        "levels": {\n            "pdh": pdh, "pdl": pdl, "pdc": pdc,\n            "orbHigh": orb_h, "orbLow": orb_l,\n            "ema9": round(e9_5[g5_last], 2),\n            "ema20": round(e20_5[g5_last], 2),\n            "ema50": round(e50_5[g5_last], 2),\n            "atr14": round(a14_5[g5_last], 2),\n        },\n        "activeSetup": latest_setup,\n        "recentSetups": list(reversed(recent_setups[-6:])),\n    }\n\n\ndef pick_safe_expiry(expiries, today_str):\n    """Avoid 0-DTE expiry-day gamma/theta traps by rolling to next expiry on expiry day."""\n    exps = sorted(set(expiries))\n    if not exps:\n        return None\n    if exps[0] == today_str and len(exps) > 1:\n        return exps[1]\n    return exps[0]\n\n\ndef compute_option_levels(ltp, spot_risk, rr=3.0, lot_size=None, max_risk_inr=3000.0):\n    """Translate spot risk into safe option SL & Target (clamped to <=35% premium and <=Rs.3,000/trade)."""\n    raw_risk = max(5.0, round(float(spot_risk) * 0.55, 2))\n    cap_pts = round(ltp * 0.35, 2)\n    if lot_size and lot_size > 0 and max_risk_inr and max_risk_inr > 0:\n        cap_pts = min(cap_pts, round(float(max_risk_inr) / float(lot_size), 2))\n    opt_risk = max(1.0, min(raw_risk, cap_pts))\n    opt_sl = round(ltp - opt_risk, 2)\n    opt_tg = round(ltp + opt_risk * float(rr), 2)\n    return opt_sl, opt_tg\n\n\nclass Scanner:\n    def __init__(self, cfg, broker):\n        self.cfg = cfg\n        self.broker = broker\n        self.last_scan = 0\n        self.last_seed = 0\n        self.seed_bars = {}\n        self.live_bars5 = {"NIFTY": {}, "BANKNIFTY": {}}\n        self.live_bars15 = {"NIFTY": {}, "BANKNIFTY": {}}\n        self.cache = None\n        self.notified = set()\n\n    def record_tick(self, index_name, price, now=None):\n        """Aggregate real-time Angel One spot quotes into live 5m & 15m OHLC bars."""\n        t = now or now_ist()\n        if not market_hours(t):\n            return\n        d_str = t.date().isoformat()\n        for mins, store in ((5, self.live_bars5), (15, self.live_bars15)):\n            slot_m = (t.minute // mins) * mins\n            slot = f"{t.hour:02d}:{slot_m:02d}"\n            key = (d_str, slot)\n            idx_store = store[index_name]\n            # Keep only today\'s live bars\n            for old_k in [k for k in idx_store if k[0] != d_str]:\n                idx_store.pop(old_k, None)\n            if key not in idx_store:\n                idx_store[key] = {"date": d_str, "time": slot, "o": price, "h": price, "l": price, "c": price}\n            else:\n                b = idx_store[key]\n                b["h"] = max(b["h"], price)\n                b["l"] = min(b["l"], price)\n                b["c"] = price\n\n    def _enrich_setup_with_option(self, setup, spot_price):\n        if not setup:\n            return None\n        s = dict(setup)\n        step = 50 if s["index"] == "NIFTY" else 100\n        atm = round(spot_price / step) * step\n        try:\n            contracts = [c for c in self.broker.instruments().values()\n                         if c["underlying"] == s["index"] and c["optionType"] == s["direction"]]\n            if not contracts:\n                return s\n            chosen_exp = pick_safe_expiry([c["expiry"] for c in contracts], today_ist())\n            exp_contracts = [c for c in contracts if c["expiry"] == chosen_exp]\n            chosen = min(exp_contracts, key=lambda c: abs(c["strike"] - atm))\n            quotes = self.broker.quotes([("NFO", chosen["token"])])\n            q = quotes.get(("NFO", chosen["token"]))\n            if q and float(q["ltp"]) >= 15.0:\n                ltp = round(float(q["ltp"]), 2)\n                opt_sl, opt_tg = compute_option_levels(ltp, s["spotRisk"], s["rr"], lot_size=chosen["lotSize"])\n                s["contract"] = dict(chosen, ltp=ltp)\n                s["optionEntry"] = ltp\n                s["optionSl"] = opt_sl\n                s["optionTarget"] = opt_tg\n                s["lotSize"] = chosen["lotSize"]\n                s["estRiskInr"] = round((ltp - opt_sl) * chosen["lotSize"] + 85, 2)\n                s["estRewardInr"] = round((opt_tg - ltp) * chosen["lotSize"] - 85, 2)\n                s["rolledExpiry"] = (chosen_exp != min(c["expiry"] for c in contracts))\n        except Exception:\n            pass\n        return s\n\n    def _atm_straddle(self, index_name, spot_price):\n        try:\n            step = 50 if index_name == "NIFTY" else 100\n            atm = round(spot_price / step) * step\n            contracts = [c for c in self.broker.instruments().values() if c["underlying"] == index_name]\n            if not contracts:\n                return None\n            chosen_exp = pick_safe_expiry([c["expiry"] for c in contracts], today_ist())\n            ce = next((c for c in contracts if c["expiry"] == chosen_exp and c["strike"] == atm and c["optionType"] == "CE"), None)\n            pe = next((c for c in contracts if c["expiry"] == chosen_exp and c["strike"] == atm and c["optionType"] == "PE"), None)\n            if not ce or not pe:\n                return None\n            qs = self.broker.quotes([("NFO", ce["token"]), ("NFO", pe["token"])])\n            qce, qpe = qs.get(("NFO", ce["token"])), qs.get(("NFO", pe["token"]))\n            if not qce or not qpe:\n                return None\n            return {"strike": atm, "expiry": chosen_exp, "combined": round(qce["ltp"] + qpe["ltp"], 2),\n                    "ceLtp": round(qce["ltp"], 2), "peLtp": round(qpe["ltp"], 2)}\n        except Exception:\n            return None\n\n    def notify_telegram(self, setup):\n        token = self.cfg.get("TELEGRAM_BOT_TOKEN", "")\n        chat_id = self.cfg.get("TELEGRAM_CHAT_ID", "")\n        if not token or not chat_id or setup["id"] in self.notified:\n            return\n        self.notified.add(setup["id"])\n        opt_line = ""\n        if setup.get("contract"):\n            opt_line = (f"\\nOption: {setup[\'contract\'][\'tradingSymbol\']} @ Rs.{setup[\'optionEntry\']}"\n                        f" | SL Rs.{setup[\'optionSl\']} | Target Rs.{setup[\'optionTarget\']}")\n        text = (f"TradePilot LIVE Setup ({setup[\'index\']} {setup[\'direction\']})\\n"\n                f"Strategy: {setup[\'strategy\']}\\n"\n                f"Spot: {setup[\'spotEntry\']} | SL: {setup[\'spotSl\']} | Target: {setup[\'spotTarget\']} (1:3 R:R)"\n                f"{opt_line}\\nReason: {setup[\'reason\']}")\n        try:\n            payload = json.dumps({"chat_id": chat_id, "text": text}).encode()\n            req = Request(f"https://api.telegram.org/bot{token}/sendMessage",\n                          data=payload, headers={"Content-Type": "application/json"})\n            with urlopen(req, timeout=8):\n                pass\n        except Exception:\n            pass\n\n    def scan(self, force=False, fetcher=fetch_yahoo_bars):\n        now_ts = time.time()\n        crossed_5m = int(now_ts // 300) > int(self.last_scan // 300)\n        if not force and self.cache and not crossed_5m and (now_ts - self.last_scan < 45):\n            return self.cache\n        is_live = market_hours()\n        live_spots = {}\n        try:\n            if is_live:\n                self.broker.ensure()\n            if self.broker.connected:\n                qs = self.broker.quotes([("NSE", t) for t in INDEX.values()])\n                for n, tok in INDEX.items():\n                    if ("NSE", tok) in qs:\n                        px = qs[("NSE", tok)]["ltp"]\n                        live_spots[n] = px\n                        if is_live:\n                            self.record_tick(n, px)\n        except Exception:\n            pass\n\n        # Refresh historical seed bars every 5 minutes (or on force)\n        need_seed = force or not self.seed_bars or (time.time() - self.last_seed > 290)\n        if need_seed:\n            for name, ysym in YAHOO_INDEX.items():\n                try:\n                    self.seed_bars[name] = (fetcher(ysym, "5d", "5m"), fetcher(ysym, "5d", "15m"))\n                except Exception:\n                    pass\n            if self.seed_bars:\n                self.last_seed = time.time()\n\n        indices = {}\n        all_setups = []\n        for name in YAHOO_INDEX:\n            try:\n                if name not in self.seed_bars:\n                    raise RuntimeError("NoSeedData")\n                base5, base15 = self.seed_bars[name]\n                b5 = merge_bars(base5, list(self.live_bars5[name].values()))\n                b15 = merge_bars(base15, list(self.live_bars15[name].values()))\n                res = analyze_index_bars(name, b5, b15, live_spot=live_spots.get(name), is_live_market=is_live)\n                if res.get("activeSetup"):\n                    res["activeSetup"] = self._enrich_setup_with_option(res["activeSetup"], res["spot"])\n                    all_setups.append(res["activeSetup"])\n                if self.broker.connected and res.get("spot"):\n                    res["straddle"] = self._atm_straddle(name, res["spot"])\n                indices[name] = res\n            except Exception as e:\n                indices[name] = {"index": name, "error": "Market scan temporarily unavailable (" + type(e).__name__ + ")."}\n\n        self.cache = {\n            "marketOpen": is_live,\n            "updatedAt": now_iso(),\n            "indices": indices,\n            "setups": all_setups,\n            "proof": BACKTEST_PROOF,\n        }\n        self.last_scan = time.time()\n        return self.cache\n\n\nclass Service:\n    def __init__(self, cfg, root):\n        self.cfg, self.root = cfg, root\n        self.lock = threading.RLock()\n        self.broker = Broker(cfg, root)\n        self.paper = Paper(root / ".paper-state-v1.json")\n        self.scanner = Scanner(cfg, self.broker)\n\n    def contract(self, token):\n        c = self.broker.instruments().get(str(token))\n        if not c:\n            raise AppError("Unknown or expired option contract.")\n        return c\n\n    def underlying(self, name):\n        if name not in INDEX:\n            raise AppError("Choose NIFTY or BANKNIFTY.")\n        return name\n\n    def order(self, b):\n        c = self.contract((b.get("contract") or {}).get("token"))\n        side, qty, sl, target = self.paper.validate(b, c)\n        kind = b.get("orderType", "MARKET")\n        if kind not in ("MARKET", "LIMIT"):\n            raise AppError("Unsupported paper order type.")\n        if kind == "LIMIT":\n            trigger = positive(b.get("limitPrice"), "Limit price")\n            if len(self.paper.data["rules"]) >= 50:\n                raise AppError("Maximum 50 rules.")\n            r = dict(c, id=uuid.uuid4().hex, side=side, qty=qty, sl=sl, target=target,\n                     triggerType="BELOW" if side == "BUY" else "ABOVE",\n                     triggerPrice=trigger, status="ARMED")\n            self.paper.data["rules"].append(r)\n            return {"message": "Paper limit rule armed; funds checked at fill."}\n        price = self.broker.trade_price(c)\n        self.paper.open(b, c, price)\n        return {"message": "Paper order filled at the received LTP (est. charges tracked separately)."}\n\n    def arm_setup(self, b, source="SCANNER"):\n        daily = self.paper.daily_stats()\n        if daily["killSwitchHit"]:\n            raise AppError(f"Daily max loss limit (-Rs.{daily[\'maxDailyLoss\']:.0f}) reached. New scanner entries locked today.")\n        setup_id = str(b.get("setupId") or "")\n        scan = self.scanner.cache or self.scanner.scan()\n        setup = next((s for s in scan.get("setups", []) if s["id"] == setup_id), None)\n        if not setup:\n            raise AppError("Setup not found. Refresh the radar and try again.", 404)\n        contract_info = setup.get("contract")\n        if not contract_info:\n            raise AppError("No live Angel One option contract matched for this setup yet.", 503)\n        c = self.contract(contract_info["token"])\n        price = self.broker.trade_price(c)\n        if price < 15.0:\n            raise AppError("Option premium is below Rs.15 (illiquid/expiring); skipped for safety.")\n        sl, target = compute_option_levels(price, setup["spotRisk"], setup.get("rr", 3.0), lot_size=c["lotSize"])\n        body = {"side": "BUY", "qty": c["lotSize"], "sl": sl, "target": target, "contract": c}\n        self.paper.open(body, c, price, source=source)\n        self.paper.data["armedSetupIds"] = (self.paper.data.get("armedSetupIds", []) + [setup_id])[-100:]\n        return {"message": f"Armed {c[\'tradingSymbol\']} (1 lot = {c[\'lotSize\']}) @ Rs.{price} | SL Rs.{sl} | Target Rs.{target}"}\n\n    def command(self, b):\n        text = str(b.get("command", "")).strip().upper()\n        if text == "EXIT ALL":\n            positions = list(self.paper.data["positions"])\n            qs = self.broker.quotes([("NFO", p["token"]) for p in positions])\n            prices = [(p["id"], self.broker.trade_price(p, qs)) for p in positions]\n            for ident, price in prices:\n                self.paper.close(ident, price)\n            return {"message": "All paper positions exited."}\n        pattern = r"(BUY|SELL) (NIFTY|BANKNIFTY) (\\d+(?:\\.\\d+)?) (CE|PE)(?: (ABOVE|BELOW) (\\d+(?:\\.\\d+)?))? QTY (\\d+)(?: SL (\\d+(?:\\.\\d+)?))?(?: TARGET (\\d+(?:\\.\\d+)?))?"\n        m = re.fullmatch(pattern, " ".join(text.split()))\n        if not m:\n            raise AppError("Use BUY NIFTY 25800 CE QTY 65 SL 110 TARGET 190, optionally ABOVE/BELOW price before QTY, or EXIT ALL.")\n        side, name, strike, opt, trigger, threshold, qty, sl, target = m.groups()\n        choices = [c for c in self.broker.instruments().values()\n                   if c["underlying"] == name and c["strike"] == float(strike) and c["optionType"] == opt]\n        expiry = b.get("expiry") or (min(c["expiry"] for c in choices) if choices else "")\n        c = next((c for c in choices if c["expiry"] == expiry), None)\n        if not c:\n            raise AppError("No matching contract for the selected expiry.")\n        body = {"side": side, "qty": qty, "sl": sl, "target": target, "contract": c}\n        if not trigger:\n            return self.order(body)\n        self.paper.validate(body, c)\n        if len(self.paper.data["rules"]) >= 50:\n            raise AppError("Maximum 50 rules.")\n        self.paper.data["rules"].append(dict(c, id=uuid.uuid4().hex, side=side, qty=int(qty),\n            sl=float(sl) if sl else None, target=float(target) if target else None,\n            triggerType=trigger, triggerPrice=positive(threshold, "Trigger"), status="ARMED"))\n        return {"message": "Paper rule armed. It runs while the server is online."}\n\n    def dispatch(self, method, path, q, b):\n        if method == "GET" and path == "/api/scanner":\n            force = q.get("force", ["0"])[0] == "1"\n            scan = self.scanner.scan(force=force)\n            with self.lock:\n                return {**scan, "config": dict(self.paper.data["scannerCfg"]), "daily": self.paper.daily_stats()}\n        with self.lock:\n            if method == "GET":\n                if path == "/api/config":\n                    self.broker.ensure()\n                    return {"configured": True, "connected": True, "mode": "PAPER_TRADING",\n                            "realMoney": False, "simulation": "LTP fills; est. 2026 charges tracked; SELL reserve 20% notional."}\n                if path == "/api/paper/state":\n                    return self.paper.snapshot()\n                if path == "/api/underlyings":\n                    qs = self.broker.quotes([("NSE", t) for t in INDEX.values()])\n                    data = {n: qs[("NSE", t)] for n, t in INDEX.items() if ("NSE", t) in qs}\n                    if len(data) != 2:\n                        raise AppError("Angel One did not return both index prices.", 503)\n                    return {"data": data}\n                if path in ("/api/expiries", "/api/options"):\n                    name = self.underlying(q.get("underlying", ["NIFTY"])[0])\n                    all_c = [c for c in self.broker.instruments().values() if c["underlying"] == name]\n                    if path == "/api/expiries":\n                        return {"expiries": sorted({c["expiry"] for c in all_c})}\n                    expiry = q.get("expiry", [""])[0]\n                    try:\n                        width = max(1, min(20, int(q.get("width", ["8"])[0])))\n                    except ValueError:\n                        raise AppError("Invalid chain width.")\n                    spot = self.broker.quotes([("NSE", INDEX[name])]).get(("NSE", INDEX[name]))\n                    if not spot:\n                        raise AppError("Index price unavailable.", 503)\n                    choices = [c for c in all_c if c["expiry"] == expiry]\n                    strikes = sorted({c["strike"] for c in choices}, key=lambda s: abs(s - spot["ltp"]))[:2 * width + 1]\n                    choices = sorted([c for c in choices if c["strike"] in strikes], key=lambda c: (c["strike"], c["optionType"]))\n                    quotes = self.broker.quotes([("NFO", c["token"]) for c in choices])\n                    contracts = [dict(c, ltp=quotes[("NFO", c["token"])]["ltp"])\n                                 for c in choices if ("NFO", c["token"]) in quotes]\n                    if choices and not contracts:\n                        raise AppError("No option prices returned by Angel One.", 503)\n                    return {"contracts": contracts, "spot": spot, "missingQuotes": len(choices) - len(contracts)}\n                raise AppError("Route not found.", 404)\n            old = copy.deepcopy(self.paper.data)\n            try:\n                if path == "/api/paper/order":\n                    result = self.order(b)\n                elif path == "/api/paper/command":\n                    result = self.command(b)\n                elif path == "/api/scanner/config":\n                    cfg = self.paper.data["scannerCfg"]\n                    if "autoTrade" in b:\n                        cfg["autoTrade"] = bool(b["autoTrade"])\n                    if "maxDailyLoss" in b:\n                        cfg["maxDailyLoss"] = round(positive(b["maxDailyLoss"], "Max daily loss"), 2)\n                    if "maxDailyTrades" in b:\n                        mt = int(positive(b["maxDailyTrades"], "Max daily trades"))\n                        cfg["maxDailyTrades"] = min(10, mt)\n                    result = {"message": "Scanner settings updated.", "config": dict(cfg)}\n                elif path == "/api/scanner/arm":\n                    result = self.arm_setup(b, source="SCANNER")\n                elif path == "/api/paper/exit":\n                    p = next((p for p in self.paper.data["positions"] if p["id"] == b.get("id")), None)\n                    if not p:\n                        raise AppError("Paper position not found.", 404)\n                    self.paper.close(p["id"], self.broker.trade_price(p))\n                    result = {"message": "Paper position exited."}\n                elif path == "/api/paper/rule/cancel":\n                    rules = self.paper.data["rules"]\n                    r = next((r for r in rules if r["id"] == b.get("id")), None)\n                    if not r:\n                        raise AppError("Rule not found.", 404)\n                    rules.remove(r)\n                    result = {"message": "Rule cancelled."}\n                elif path == "/api/paper/reset":\n                    keep_cfg = dict(self.paper.data.get("scannerCfg", DEFAULT_SCANNER_CFG))\n                    self.paper.data = {\n                        "version": 1, "realized": 0, "estimatedCharges": 0.0,\n                        "positions": [], "orders": [], "rules": [],\n                        "scannerCfg": keep_cfg, "armedSetupIds": [],\n                    }\n                    result = {"message": "Paper account reset to 100000."}\n                else:\n                    raise AppError("Route not found.", 404)\n                self.paper.save()\n                return result\n            except Exception:\n                self.paper.data = old\n                raise\n\n    def monitor(self):\n        while True:\n            try:\n                if market_hours():\n                    # Feed live Angel One index quotes into real-time 5m/15m candle aggregator (outside paper lock)\n                    try:\n                        self.broker.ensure()\n                        idx_qs = self.broker.quotes([("NSE", t) for t in INDEX.values()])\n                        for n, tok in INDEX.items():\n                            if ("NSE", tok) in idx_qs:\n                                self.scanner.record_tick(n, idx_qs[("NSE", tok)]["ltp"])\n                    except Exception:\n                        pass\n\n                    scan = self.scanner.scan()\n                    with self.lock:\n                        cfg = self.paper.data["scannerCfg"]\n                        daily = self.paper.daily_stats()\n                        armed = set(self.paper.data.get("armedSetupIds", []))\n                        for s in scan.get("setups", []):\n                            if s.get("status") != "LIVE":\n                                continue\n                            self.scanner.notify_telegram(s)\n                            per_idx = daily["byIndexToday"].get(s["index"], 0)\n                            if (cfg.get("autoTrade") and s["id"] not in armed\n                                    and not daily["killSwitchHit"]\n                                    and per_idx < 2\n                                    and daily["scannerTradesToday"] < daily["maxDailyTrades"]\n                                    and not any(p["underlying"] == s["index"] for p in self.paper.data["positions"])):\n                                try:\n                                    self.arm_setup({"setupId": s["id"]}, source="SCANNER")\n                                    self.paper.save()\n                                    daily = self.paper.daily_stats()\n                                    armed.add(s["id"])\n                                except Exception:\n                                    pass\n\n                with self.lock:\n                    items = self.paper.data["positions"] + self.paper.data["rules"]\n                    if items and market_hours():\n                        quotes = self.broker.quotes([("NFO", p["token"]) for p in items], force=True)\n                        old = copy.deepcopy(self.paper.data)\n                        try:\n                            for p in list(self.paper.data["positions"]):\n                                try:\n                                    price = self.broker.trade_price(p, quotes)\n                                except AppError:\n                                    continue\n                                p["ltp"] = price\n                                p["pnl"] = (price - p["entry"]) * p["qty"] * (1 if p["side"] == "BUY" else -1)\n                                # Trail SL to breakeven at +1.5R for scanner BUY positions\n                                init_r = p.get("initialRisk")\n                                if p.get("source") == "SCANNER" and p["side"] == "BUY" and init_r and not p.get("trailed"):\n                                    if price >= p["entry"] + init_r * 1.5:\n                                        p["sl"] = round(p["entry"] + 2.0, 2)\n                                        p["trailed"] = True\n                                sl, target = p["sl"], p["target"]\n                                hit = ((sl and price <= sl) or (target and price >= target)) if p["side"] == "BUY" else ((sl and price >= sl) or (target and price <= target))\n                                eod_exit = p.get("source") == "SCANNER" and now_ist().time() >= dt.time(15, 10)\n                                if hit:\n                                    self.paper.close(p["id"], price, "TRAIL/SL/TG" if p.get("trailed") else "SL/TARGET")\n                                elif eod_exit:\n                                    self.paper.close(p["id"], price, "EOD")\n                            for r in list(self.paper.data["rules"]):\n                                if r["status"] != "ARMED":\n                                    continue\n                                try:\n                                    price = self.broker.trade_price(r, quotes)\n                                except AppError:\n                                    continue\n                                hit = price >= r["triggerPrice"] if r["triggerType"] == "ABOVE" else price <= r["triggerPrice"]\n                                if hit:\n                                    try:\n                                        self.paper.open(r, self.contract(r["token"]), price, "RULE")\n                                        self.paper.data["rules"].remove(r)\n                                    except AppError:\n                                        r["status"] = "REJECTED"\n                            self.paper.save()\n                        except Exception:\n                            self.paper.data = old\n                            raise\n            except Exception as e:\n                print("Background check:", type(e).__name__, flush=True)\n            time.sleep(5)\n\n\ndef handler_for(service):\n    class Handler(BaseHTTPRequestHandler):\n        server_version = "TradePilot"\n\n        def log_message(self, *args):\n            pass\n\n        def reply(self, code, data):\n            body = json.dumps(data, allow_nan=False).encode()\n            self.send_response(code)\n            self.send_header("Content-Type", "application/json")\n            self.send_header("Content-Length", str(len(body)))\n            self.send_header("Cache-Control", "no-store")\n            self.send_header("X-Content-Type-Options", "nosniff")\n            if self.headers.get("Origin") == service.cfg["FRONTEND_ORIGIN"]:\n                self.send_header("Access-Control-Allow-Origin", service.cfg["FRONTEND_ORIGIN"])\n                self.send_header("Vary", "Origin")\n                self.send_header("Access-Control-Allow-Headers", "Content-Type, X-TradePilot-Key")\n                self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")\n            self.end_headers()\n            self.wfile.write(body)\n\n        def do_OPTIONS(self):\n            self.reply(200, {})\n\n        def run_request(self):\n            parsed = urlsplit(self.path)\n            if parsed.path == "/health" and self.command == "GET":\n                return self.reply(200, {"status": "ok", "app": "TradePilot", "mode": "PAPER_TRADING", "realMoney": False})\n            origin = self.headers.get("Origin")\n            if origin and origin != service.cfg["FRONTEND_ORIGIN"]:\n                return self.reply(403, {"error": "Origin not allowed."})\n            expected = service.cfg.get("APP_ACCESS_TOKEN", "")\n            supplied = self.headers.get("X-TradePilot-Key", "")\n            if not expected or not hmac.compare_digest(expected.encode(), supplied.encode()):\n                return self.reply(401, {"error": "App access key is missing or incorrect."})\n            try:\n                if parsed.path == "/angel/status" and self.command == "GET":\n                    with service.lock:\n                        service.broker.ensure()\n                    return self.reply(200, {"connected": True, "state": "verified"})\n                body = {}\n                if self.command == "POST":\n                    size = int(self.headers.get("Content-Length", "0"))\n                    if size <= 0 or size > 16384:\n                        raise AppError("Invalid request size.", 413)\n                    self.connection.settimeout(10)\n                    body = json.loads(self.rfile.read(size))\n                    if not isinstance(body, dict):\n                        raise AppError("Expected a JSON object.")\n                result = service.dispatch(self.command, parsed.path, parse_qs(parsed.query), body)\n                self.reply(200, result)\n            except AppError as e:\n                self.reply(e.status, {"error": str(e)})\n            except (ValueError, KeyError, TypeError):\n                self.reply(400, {"error": "Invalid request or server configuration."})\n            except Exception:\n                self.reply(503, {"error": "Server operation failed. Check service logs."})\n\n        do_GET = run_request\n        do_POST = run_request\n    return Handler\n\n\ndef main():\n    cfg = read_env(ROOT / ".env")\n    needed = ("ANGEL_API_KEY", "ANGEL_CLIENT_CODE", "ANGEL_PIN", "ANGEL_TOTP_SECRET",\n              "ANGEL_PUBLIC_IP", "APP_ACCESS_TOKEN", "FRONTEND_ORIGIN")\n    missing = [k for k in needed if not cfg.get(k)]\n    if missing:\n        raise RuntimeError("Missing settings: " + ", ".join(missing))\n    service = Service(cfg, ROOT)\n    server = ThreadingHTTPServer(("127.0.0.1", int(os.environ.get("PORT", "3000"))), handler_for(service))\n    threading.Thread(target=service.monitor, daemon=True).start()\n    print("TradePilot private PAPER_TRADING + Radar API ready.", flush=True)\n    server.serve_forever()\n\n\nif __name__ == "__main__":\n    main()\n', 'server.js': 'import { spawn } from "node:child_process";\nimport { fileURLToPath } from "node:url";\nconst path = fileURLToPath(new URL("./backend.py", import.meta.url));\nconst child = spawn("/usr/bin/python3", ["-u", path], { stdio: "inherit" });\nfor (const signal of ["SIGTERM", "SIGINT"]) process.on(signal, () => child.kill(signal));\nchild.on("error", () => { console.error("Backend could not start."); process.exit(1); });\nchild.on("exit", (code, signal) => process.exit(code ?? (signal ? 0 : 1)));\n\n', 'test_backend.py': 'import copy\nimport datetime as dt\nimport io\nimport json\nfrom pathlib import Path\nimport tempfile\nimport unittest\nfrom unittest.mock import patch\nimport backend as b\n\n\nclass Tests(unittest.TestCase):\n    def setUp(self):\n        self.tmp = tempfile.TemporaryDirectory()\n        self.root = Path(self.tmp.name)\n        self.c = dict(token="123", tradingSymbol="NIFTY30DEC9925000CE", underlying="NIFTY",\n                      expiry="2099-12-30", strike=25000, lotSize=65, optionType="CE", exchange="NFO")\n        self.p = b.Paper(self.root / "paper.json")\n\n    def tearDown(self):\n        self.tmp.cleanup()\n\n    def test_totp_rfc(self):\n        self.assertEqual(b.totp("GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ", 59), "287082")\n\n    def test_persistence_account_exit(self):\n        self.p.open({"side": "BUY", "qty": 65}, self.c, 100)\n        self.assertEqual(self.p.snapshot()["account"]["available"], 93500)\n        self.p.save()\n        restored = b.Paper(self.p.path)\n        restored.close(restored.data["positions"][0]["id"], 110)\n        self.assertEqual(restored.snapshot()["account"]["equity"], 100650)\n        self.assertGreater(restored.snapshot()["account"]["estimatedCharges"], 50)\n        self.assertLess(restored.snapshot()["account"]["netRealized"], 650)\n        self.assertEqual(restored.data["orders"][-1]["side"], "SELL")\n\n    def test_invalid_quantity_price_and_side(self):\n        for data in ({"side": "BUY", "qty": 1}, {"side": "BUY", "qty": float("nan")},\n                     {"side": "BUY", "qty": -65}, {"side": "REAL", "qty": 65}):\n            with self.assertRaises(b.AppError):\n                self.p.open(data, self.c, 100)\n        self.assertFalse(self.p.data["positions"])\n\n    def test_short_reserve_and_pnl(self):\n        c = dict(self.c, strike=1000, lotSize=25)\n        self.p.open({"side": "SELL", "qty": 25}, c, 100)\n        self.assertEqual(self.p.snapshot()["account"]["available"], 95000)\n        self.p.close(self.p.data["positions"][0]["id"], 90)\n        self.assertEqual(self.p.snapshot()["account"]["realized"], 250)\n        self.assertEqual(self.p.data["orders"][-1]["side"], "BUY")\n\n    def test_sl_validation_and_funds(self):\n        for data in ({"side": "BUY", "qty": 65, "sl": 120},\n                     {"side": "SELL", "qty": 65, "target": 120},\n                     {"side": "BUY", "qty": 100000}):\n            with self.assertRaises(b.AppError):\n                self.p.open(data, self.c, 100)\n\n    def test_master_expiry_and_scaling(self):\n        row = dict(exch_seg="NFO", instrumenttype="OPTIDX", name="NIFTY",\n                   expiry="30DEC2099", symbol="NIFTY30DEC9925000CE", token="123",\n                   lotsize="65", strike="2500000")\n        parsed = b.normalize_instruments([row, dict(row, expiry="01JAN2000"), dict(row, token="<script>")])\n        self.assertEqual(len(parsed), 1)\n        self.assertEqual(parsed["123"]["strike"], 25000)\n        self.assertEqual(parsed["123"]["lotSize"], 65)\n\n    def test_no_live_order_transport(self):\n        broker = b.Broker({}, self.root)\n        with self.assertRaises(b.AppError):\n            broker.request("/rest/secure/angelbroking/order/v1/placeOrder", {})\n\n    def test_stale_prices_no_fills(self):\n        broker = b.Broker({}, self.root)\n        import time\n        q = {("NFO", "123"): dict(ltp=100, received=time.time(), feed=time.time() - 120)}\n        with patch.object(b, "market_hours", return_value=True):\n            with self.assertRaises(b.AppError):\n                broker.trade_price(self.c, q)\n            q[("NFO", "123")]["feed"] = time.time()\n            self.assertEqual(broker.trade_price(self.c, q), 100)\n        with patch.object(b, "market_hours", return_value=False):\n            with self.assertRaises(b.AppError):\n                broker.trade_price(self.c, q)\n\n    def service(self):\n        svc = b.Service({"APP_ACCESS_TOKEN": "test-private-app-key",\n                         "FRONTEND_ORIGIN": "https://samim29abu-sketch.github.io"}, self.root)\n        svc.broker.contracts = {"123": self.c}\n        svc.broker.instruments = lambda: svc.broker.contracts\n        svc.broker.ensure = lambda: None\n        svc.broker.trade_price = lambda *args: 100\n        svc.broker.quotes = lambda pairs, force=False: {("NFO", "123"): {"ltp": 100, "received": 1e12, "feed": 1e12}}\n        return svc\n\n    def test_client_cannot_forge_contract_or_price(self):\n        svc = self.service()\n        fake = dict(self.c, tradingSymbol="FORGED", lotSize=1, ltp=1)\n        svc.dispatch("POST", "/api/paper/order", {}, {"side": "BUY", "qty": 65, "contract": fake})\n        pos = svc.paper.data["positions"][0]\n        self.assertEqual(pos["entry"], 100)\n        self.assertEqual(pos["tradingSymbol"], self.c["tradingSymbol"])\n\n    def test_save_failure_rolls_back(self):\n        svc = self.service()\n        with patch.object(svc.paper, "save", side_effect=OSError()):\n            with self.assertRaises(OSError):\n                svc.dispatch("POST", "/api/paper/order", {}, {"side": "BUY", "qty": 65, "contract": self.c})\n        self.assertEqual(svc.paper.data["positions"], [])\n\n    def test_limit_command_cancel_and_reset(self):\n        svc = self.service()\n        svc.dispatch("POST", "/api/paper/order", {}, dict(side="BUY", qty=65, contract=self.c, orderType="LIMIT", limitPrice=90))\n        rule = svc.paper.data["rules"][0]\n        self.assertEqual(rule["triggerType"], "BELOW")\n        svc.dispatch("POST", "/api/paper/rule/cancel", {}, {"id": rule["id"]})\n        svc.dispatch("POST", "/api/paper/command", {}, {"command": "BUY NIFTY 25000 CE ABOVE 105 QTY 65 SL 90 TARGET 120"})\n        self.assertEqual(len(svc.paper.data["rules"]), 1)\n        svc.dispatch("POST", "/api/paper/reset", {}, {})\n        self.assertEqual(svc.paper.snapshot()["account"]["equity"], 100000)\n        self.assertEqual(svc.paper.data["rules"], [])\n\n    def test_holiday_expiry_rollover_and_option_sl_clamp(self):\n        # Tuesday 24 Nov 2026 is Guru Nanak Jayanti (NSE holiday)\n        self.assertFalse(b.market_hours(dt.datetime(2026, 11, 24, 10, 30, tzinfo=b.IST)))\n        # Monday 23 Nov 2026 is a normal market day\n        self.assertTrue(b.market_hours(dt.datetime(2026, 11, 23, 10, 30, tzinfo=b.IST)))\n        # Expiry-day rollover skips 0-DTE and selects next expiry\n        self.assertEqual(b.pick_safe_expiry(["2026-11-23", "2026-12-01"], "2026-11-23"), "2026-12-01")\n        self.assertEqual(b.pick_safe_expiry(["2026-11-23", "2026-12-01"], "2026-11-22"), "2026-11-23")\n        # Option SL clamp prevents >35% premium risk\n        sl, tg = b.compute_option_levels(ltp=50.0, spot_risk=100.0, rr=3.0)\n        self.assertEqual(sl, 32.5)\n        self.assertEqual(tg, 102.5)\n        # Option SL clamp enforces Rs.3,000 catastrophe max risk per trade on volatile BANKNIFTY\n        sl_bn, tg_bn = b.compute_option_levels(ltp=1247.65, spot_risk=200.66, rr=3.0, lot_size=30)\n        self.assertEqual(sl_bn, 1147.65)\n        self.assertEqual(tg_bn, 1547.65)\n\n    def test_live_tick_candle_aggregator_and_stale_day_guard(self):\n        sc = b.Scanner({}, b.Broker({}, self.root))\n        t1 = dt.datetime(2026, 11, 23, 9, 31, tzinfo=b.IST)\n        t2 = dt.datetime(2026, 11, 23, 9, 34, tzinfo=b.IST)\n        sc.record_tick("NIFTY", 25800.0, now=t1)\n        sc.record_tick("NIFTY", 25840.0, now=t2)\n        bar = sc.live_bars5["NIFTY"][("2026-11-23", "09:30")]\n        self.assertEqual((bar["o"], bar["h"], bar["l"], bar["c"]), (25800.0, 25840.0, 25800.0, 25840.0))\n\n        # Verify yesterday\'s bar is NEVER marked LIVE on Monday morning at 09:16!\n        day1_5m = [{"date": "2026-11-19", "time": f"{9 + (15 + 5*i)//60:02d}:{(15 + 5*i)%60:02d}",\n                    "o": 24900 + i*2, "h": 24930 + i*2, "l": 24890 + i*2, "c": 24920 + i*2} for i in range(25)]\n        pdh = max(x["h"] for x in day1_5m)\n        day2_5m = [\n            {"date": "2026-11-20", "time": "09:15", "o": pdh - 20, "h": pdh - 5, "l": pdh - 35, "c": pdh - 10},\n            {"date": "2026-11-20", "time": "09:20", "o": pdh - 10, "h": pdh + 2, "l": pdh - 20, "c": pdh - 4},\n            {"date": "2026-11-20", "time": "09:25", "o": pdh - 4, "h": pdh + 4, "l": pdh - 15, "c": pdh - 2},\n            {"date": "2026-11-20", "time": "09:30", "o": pdh - 2, "h": pdh + 30, "l": pdh - 8, "c": pdh + 26},\n            {"date": "2026-11-20", "time": "09:35", "o": pdh + 26, "h": pdh + 35, "l": pdh + 20, "c": pdh + 30},\n        ]\n        bars15 = [\n            {"date": "2026-11-19", "time": f"{9 + (15 + 15*i)//60:02d}:{(15 + 15*i)%60:02d}",\n             "o": 24850 + i*12, "h": 24880 + i*12, "l": 24840 + i*12, "c": 24870 + i*12} for i in range(15)\n        ] + [{"date": "2026-11-20", "time": "09:15", "o": pdh - 20, "h": pdh + 25, "l": pdh - 30, "c": pdh + 20}]\n        mon_open = dt.datetime(2026, 11, 23, 9, 16, tzinfo=b.IST)\n        res_stale = b.analyze_index_bars("NIFTY", day1_5m + day2_5m, bars15, is_live_market=True, now=mon_open)\n        self.assertEqual(res_stale["activeSetup"]["status"], "PREVIEW")\n\n    def test_scanner_pdh_break_and_arm_and_kill_switch(self):\n        day1_5m = [{"date": "2026-11-19", "time": f"{9 + (15 + 5*i)//60:02d}:{(15 + 5*i)%60:02d}",\n                    "o": 24900 + i*2, "h": 24930 + i*2, "l": 24890 + i*2, "c": 24920 + i*2} for i in range(25)]\n        pdh = max(x["h"] for x in day1_5m)\n        day2_5m = [\n            {"date": "2026-11-20", "time": "09:15", "o": pdh - 20, "h": pdh - 5, "l": pdh - 35, "c": pdh - 10},\n            {"date": "2026-11-20", "time": "09:20", "o": pdh - 10, "h": pdh + 2, "l": pdh - 20, "c": pdh - 4},\n            {"date": "2026-11-20", "time": "09:25", "o": pdh - 4, "h": pdh + 4, "l": pdh - 15, "c": pdh - 2},\n            {"date": "2026-11-20", "time": "09:30", "o": pdh - 2, "h": pdh + 30, "l": pdh - 8, "c": pdh + 26},\n            {"date": "2026-11-20", "time": "09:35", "o": pdh + 26, "h": pdh + 35, "l": pdh + 20, "c": pdh + 30},\n        ]\n        bars15 = [\n            {"date": "2026-11-19", "time": f"{9 + (15 + 15*i)//60:02d}:{(15 + 15*i)%60:02d}",\n             "o": 24850 + i*12, "h": 24880 + i*12, "l": 24840 + i*12, "c": 24870 + i*12} for i in range(15)\n        ] + [\n            {"date": "2026-11-20", "time": "09:15", "o": pdh - 20, "h": pdh + 25, "l": pdh - 30, "c": pdh + 20},\n        ]\n        # 09:36 IST right after the 09:30 bar closed at 09:35!\n        live_now = dt.datetime(2026, 11, 20, 9, 36, tzinfo=b.IST)\n        res = b.analyze_index_bars("NIFTY", day1_5m + day2_5m, bars15, is_live_market=True, now=live_now)\n        self.assertEqual(res["htfBias"], "BULLISH")\n        self.assertIsNotNone(res["activeSetup"])\n        self.assertEqual(res["activeSetup"]["direction"], "CE")\n        self.assertEqual(res["activeSetup"]["status"], "LIVE")\n\n        svc = self.service()\n        enriched = svc.scanner._enrich_setup_with_option(res["activeSetup"], res["spot"])\n        svc.scanner.cache = {"marketOpen": True, "updatedAt": b.now_iso(), "indices": {"NIFTY": res},\n                             "setups": [enriched], "proof": b.BACKTEST_PROOF}\n        cfg_res = svc.dispatch("POST", "/api/scanner/config", {}, {"autoTrade": True, "maxDailyLoss": 2500, "maxDailyTrades": 4})\n        self.assertTrue(cfg_res["config"]["autoTrade"])\n        self.assertEqual(cfg_res["config"]["maxDailyLoss"], 2500)\n\n        arm_res = svc.dispatch("POST", "/api/scanner/arm", {}, {"setupId": enriched["id"]})\n        self.assertIn("Armed", arm_res["message"])\n        self.assertEqual(len(svc.paper.data["positions"]), 1)\n        self.assertEqual(svc.paper.data["positions"][0]["source"], "SCANNER")\n\n        # Verify daily kill-switch blocks new scanner entry\n        svc.paper.data["positions"][0]["pnl"] = -3000\n        with self.assertRaises(b.AppError):\n            svc.dispatch("POST", "/api/scanner/arm", {}, {"setupId": enriched["id"]})\n\n    def test_http_auth_cors_and_config(self):\n        svc = self.service()\n\n        class Socket:\n            def __init__(self, request):\n                self.input = io.BytesIO(request)\n                self.output = bytearray()\n\n            def makefile(self, *a, **k):\n                return self.input\n\n            def sendall(self, data):\n                self.output.extend(data)\n\n            def settimeout(self, value):\n                pass\n\n        def request(headers):\n            raw = ("GET /api/config HTTP/1.0\\r\\nHost: localhost\\r\\n" + headers + "\\r\\n").encode()\n            sock = Socket(raw)\n            b.handler_for(svc)(sock, ("127.0.0.1", 1234), None)\n            return bytes(sock.output).decode()\n\n        self.assertIn("401 Unauthorized", request(""))\n        result = request("X-TradePilot-Key: test-private-app-key\\r\\nOrigin: https://samim29abu-sketch.github.io\\r\\n")\n        self.assertIn("200 OK", result)\n        self.assertIn("Access-Control-Allow-Origin: https://samim29abu-sketch.github.io", result)\n        self.assertIn(\'"configured": true\', result)\n        self.assertNotIn("jwtToken", result)\n        self.assertIn("403 Forbidden", request("X-TradePilot-Key: test-private-app-key\\r\\nOrigin: https://evil.example\\r\\n"))\n\n\nif __name__ == "__main__":\n    unittest.main()\n'}

def write_private(path, content):
    fd, tmp = tempfile.mkstemp(dir=path.parent, prefix=".install-")
    try:
        with os.fdopen(fd, "w") as f:
            os.fchmod(f.fileno(), 0o600)
            f.write(content)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp):
            os.unlink(tmp)

def main():
    root = Path("/home/admin/tradepilot-backend")
    if os.geteuid() == 0:
        raise SystemExit("Run this as admin with python3, not sudo python3.")
    if not (root / ".env").is_file() or not (root / "server.js").is_file():
        raise SystemExit("Expected TradePilot files are missing. Nothing changed.")
    original_env = (root / ".env").read_text()
    cfg = {}
    for line in original_env.splitlines():
        if "=" in line and not line.lstrip().startswith("#"):
            k, v = line.split("=", 1)
            cfg[k.strip()] = v.strip().strip('"').strip("'")
    missing = [k for k in ("ANGEL_API_KEY", "ANGEL_CLIENT_CODE", "ANGEL_PIN", "ANGEL_TOTP_SECRET") if not cfg.get(k)]
    if missing:
        raise SystemExit("Missing settings: " + ", ".join(missing))
    command = subprocess.check_output(
        ["systemctl", "show", "tradepilot.service", "--property=ExecStart", "--value", "--no-pager"], text=True)
    if "/home/admin/tradepilot-backend/server.js" not in command:
        raise SystemExit("Service startup path differs. Nothing changed.")
    print("Testing bundled backend before installation...", flush=True)
    with tempfile.TemporaryDirectory(prefix="tradepilot-check-") as directory:
        for name, content in FILES.items():
            Path(directory, name).write_text(content)
        subprocess.run([sys.executable, "-m", "unittest", "-v", "test_backend"], cwd=directory, check=True)
        subprocess.run(["node", "--check", str(Path(directory, "server.js"))], check=True)

    existing_access = cfg.get("APP_ACCESS_TOKEN", "")
    if len(existing_access) >= 16 and not any(c.isspace() for c in existing_access) and not any(c in existing_access for c in "'\""):
        print("\nPress Enter to KEEP your existing App Access Key, or type a new one (16+ characters).")
        access = getpass.getpass("App access key (hidden, Enter to keep existing): ").strip()
        if not access:
            access = existing_access
            print("Keeping existing App Access Key.")
        else:
            again = getpass.getpass("Confirm new app access key (hidden): ").strip()
            if len(access) < 16 or access != again or any(c.isspace() for c in access) or any(c in access for c in "'\""):
                raise SystemExit("Use matching keys of 16+ characters without spaces or quotes. Nothing changed.")
    else:
        print("\nChoose an APP ACCESS KEY for the phone app (16+ characters).")
        print("This is NOT your Angel One API key or MPIN. Enter the same value in the app Connection screen.")
        access = getpass.getpass("New app access key (hidden): ").strip()
        again = getpass.getpass("Confirm app access key (hidden): ").strip()
        if len(access) < 16 or access != again or any(c.isspace() for c in access) or any(c in access for c in "'\""):
            raise SystemExit("Use matching keys of 16+ characters without spaces or quotes. Nothing changed.")

    updates = {"APP_ACCESS_TOKEN": access, "FRONTEND_ORIGIN": "https://samim29abu-sketch.github.io",
               "ANGEL_PUBLIC_IP": "16.4.2.101"}
    lines = [line for line in original_env.splitlines()
             if not ("=" in line and line.split("=", 1)[0].strip() in updates)]
    lines += [k + "=" + v for k, v in updates.items()]
    backup = root / ".tradepilot-backups" / str(time.time_ns())
    backup.mkdir(parents=True, mode=0o700)
    os.chmod(backup.parent, 0o700)
    names = [".env", "server.js", "backend.py", "test_backend.py"]
    originals = {}
    for name in names:
        p = root / name
        originals[name] = p.read_bytes() if p.exists() else None
        if p.exists():
            shutil.copy2(p, backup / name)
            os.chmod(backup / name, 0o600)
    try:
        for name, content in FILES.items():
            write_private(root / name, content)
        write_private(root / ".env", "\n".join(lines) + "\n")
        subprocess.run(["sudo", "systemctl", "restart", "tradepilot.service"], check=True)
        ready = False
        for attempt in range(10):
            try:
                req = Request("http://127.0.0.1:3000/api/paper/state",
                              headers={"X-TradePilot-Key": access})
                with urlopen(req, timeout=5) as response:
                    state = json.load(response)
                if "account" in state and "positions" in state:
                    ready = True
                    break
            except Exception:
                time.sleep(2)
        if not ready:
            raise RuntimeError("New API did not become ready")
    except Exception:
        print("Install check failed. Restoring previous files.", flush=True)
        for name, content in originals.items():
            path = root / name
            if content is None:
                path.unlink(missing_ok=True)
            else:
                path.write_bytes(content)
                os.chmod(path, 0o600)
        subprocess.run(["sudo", "systemctl", "restart", "tradepilot.service"], check=False)
        raise SystemExit("Previous server restored. Send this message to ChatGPT.")

    print("\nINSTALLED: Private paper-trading API is running.", flush=True)
    print("BACKUP:", backup)
    for label, route, timeout in [
        ("ANGEL CONNECTION", "/api/config", 90),
        ("INDEX PRICES", "/api/underlyings", 45),
        ("OPTION EXPIRIES", "/api/expiries?underlying=NIFTY", 90)]:
        try:
            request = Request("http://127.0.0.1:3000" + route, headers={"X-TradePilot-Key": access})
            with urlopen(request, timeout=timeout) as response:
                result = json.load(response)
            if route == "/api/config":
                print(label + ":", "VERIFIED" if result.get("configured") else "PENDING", flush=True)
            elif "expiries" in result:
                print(label + ":", len(result["expiries"]), "loaded", flush=True)
            else:
                print(label + ":", ", ".join(result.get("data", {})), flush=True)
        except HTTPError as error:
            print(label + ": HTTP", error.code, "(no credentials printed)", flush=True)
        except Exception as error:
            print(label + ":", type(error).__name__, "(retry from app)", flush=True)
    print("\nPhone Connection URL: https://tradepilot.16-4-2-101.sslip.io")
    print("Enter the APP ACCESS KEY you just chose, then tap Connect.")
    print("Trades are simulated. No real-money order endpoint exists.")
    print("Paper fills require recent exchange timestamps during weekday market hours.")
    print("SELL reserve is a simulation: 20% of strike notional; fees/slippage are not modeled.")

if __name__ == "__main__":
    main()

